  //   print(simplify(theta**3/2 - 9*theta/2))
  //   => sqrt(2)
  it.todo("print(simplify(theta**3/2 - 9*theta/2))");
  // text that is not a string
  //   print(simplify(-theta**3/2 + 11*theta/2))
  //   => sqrt(3)
  it.todo("print(simplify(-theta**3/2 + 11*theta/2))");
  it("a.root", () => {
    expect(sympyStr(add(pow(2, rational(1, 2)), pow(3, rational(1, 2))))).toBe('sqrt(2) + sqrt(3)');
  });
  it("a.coeffs()", () => {
    const v1 = new AlgebraicNumber(add(pow(2, rational(1, 2)), pow(3, rational(1, 2))), [rational(1, 2), rational(0), rational(-9, 2), rational(0)], {}).coeffs();
    expect(sympyStr([at(v1, 0), at(v1, 3), at(v1, 2), at(v1, 3)])).toBe('[1/2, 0, -9/2, 0]');
  });
